export const WEAPONS: Weapon[] = [
  // Swords
  { id: 'iron_sword', lore: 'Forgée par dizaines à Grievy Town, du temps où la milice commandait encore par lots. La plupart n\'ont jamais servi — elles rouillent dans les râteliers de la caserne vide. Sur celle-ci, le tranchant porte des entailles, et quelqu\'un a resserré le cuir de la poignée avec du fil de pêche. Celle-ci, si.', name: 'Épée de Fer', description: 'Une lame basique en fer. Fiable.', rarity: ItemRarity.COMMON, type: ItemType.WEAPON, icon: 'item_iron_sword', value: 40, weaponType: WeaponType.SWORD, damage: 17, magicDamage: 8, bonusStats: {}, attackSpeed: 1.0, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 13, max: 20 }, substats: [{ key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'steel_sword', lore: 'L\'acier vient des fourneaux d\'avant l\'Effondrement, quand Ashford fournissait la moitié de Velmara. On n\'en forge plus d\'aussi bon — plus personne n\'a le temps de laisser reposer le métal. Le forgeron de Grievy Town garde les dernières barres sous son établi. Il n\'en sort une que quand il estime que la lame servira à quelque chose qui en vaut la peine.', name: 'Épée d\'Acier', description: 'Une lame d\'acier bien forgée.', rarity: ItemRarity.UNCOMMON, type: ItemType.WEAPON, icon: 'item_steel_sword', value: 120, weaponType: WeaponType.SWORD, damage: 22, magicDamage: 10, bonusStats: {}, attackSpeed: 1.0, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 17, max: 26 }, substats: [{ key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }] } },
  { id: 'storm_sword', lore: 'Un ingénieur de Volterra l\'a trempée dans un arc du réseau, un soir de garde, pour vérifier une théorie. La lame a pris la charge et ne l\'a jamais rendue. Il a consigné le résultat dans son registre d\'une main qui tremblait encore, puis a écrit dessous : ne pas répéter. Il n\'a essayé qu\'une seule fois.', name: 'Épée de Tempête', description: 'Une lame qui crépite de l\'éclair de Volterra.', rarity: ItemRarity.RARE, type: ItemType.WEAPON, icon: 'item_storm_sword', value: 380, element: ElementType.LIGHTNING, weaponType: WeaponType.SWORD, damage: 28, magicDamage: 13, bonusStats: {}, attackSpeed: 1.1, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 22, max: 34 }, substats: [{ key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }] } },
  { id: 'dragonfang_sword', name: 'Croc-Dragon', description: 'Forgée à partir des crocs de Pyrath. Brûle à chaque frappe.', rarity: ItemRarity.EPIC, type: ItemType.WEAPON, icon: 'item_dragonfang_sword', value: 1200, element: ElementType.FIRE, weaponType: WeaponType.SWORD, damage: 36, magicDamage: 16, bonusStats: {}, attackSpeed: 1.0, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 28, max: 43 }, substats: [{ key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }] }, lore: 'Pyrath ne perdait ses crocs que par choix — les prêtres d\'Ignis Reach l\'enseignaient depuis toujours. On a trouvé ceux-là plantés dans la roche, à hauteur d\'homme, comme déposés. Le forgeron qui les a montés en lame a travaillé sans gants ; il jurait que la chaleur lui montrait où couper. Nul ne sait pourquoi le dieu les a laissés. Peut-être savait-il déjà qu\'on en aurait besoin contre lui.' },
  { id: 'velmara_blade', name: 'Lame de Velmara', description: 'Une lame qui change d\'élément à chaque frappe.', rarity: ItemRarity.LEGENDARY, type: ItemType.WEAPON, icon: 'item_velmara_blade', value: 5000, weaponType: WeaponType.SWORD, damage: 45, magicDamage: 20, bonusStats: {}, attackSpeed: 1.2, lore: 'Aucun forgeron de Velmara ne prétend l\'avoir créée. On la trouva dans la grotte la plus profonde de Terravast, posée sur un socle que personne n\'avait taillé, intacte depuis des siècles. Elle change d\'élément sans effort, sans bruit, comme on change d\'avis. Ovan pense qu\'elle date d\'avant le partage du monde entre les six, quand les éléments ne savaient pas encore se tenir séparés. Les divinités s\'éteignent une à une ; elle, elle se souvient de toutes.', equipRanges: { mainStat: { key: 'ATK_FLAT', min: 35, max: 55 }, substats: [{ key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 2, max: 3, isPercentage: true }] } },
  { id: 'echo_blade', name: 'Lame de l\'Écho', description: 'Une lame qui se duplique à chaque coup, frappant deux fois.', rarity: ItemRarity.MYTHIC, type: ItemType.WEAPON, icon: 'item_echo_blade', value: 12000, weaponType: WeaponType.SWORD, damage: 59, magicDamage: 27, bonusStats: {}, attackSpeed: 1.3, lore: 'Certaines armes sont fabriquées. D\'autres sont souhaitées à l\'existence — par un désir assez ancien, assez patient, pour que le monde finisse par céder. Chaque coup qu\'elle porte revient une seconde fois, un instant plus tard, comme si le geste refusait d\'être fini. Ovan a passé une nuit entière à l\'étudier, puis l\'a rendue sans un mot. Il n\'a plus jamais posé de questions sur elle.', equipRanges: { mainStat: { key: 'ATK_FLAT', min: 46, max: 71 }, substats: [{ key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 2, max: 3, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'SPD_FLAT', min: 4, max: 7 }] } },
  { id: 'magma_greatsword', lore: 'La lave d\'Ignis Reach refroidit parfois en formes étranges — des colonnes, des arches, des mains. Celle-ci avait déjà un tranchant quand on l\'a trouvée, comme si la coulée s\'était souvenue d\'avoir été une arme. Les carriers d\'Ashford l\'ont dégagée au burin et personne n\'a voulu la garder. Trop lourde, disaient-ils. Ce n\'était pas le poids.', name: 'Espadon de Magma', description: 'Une lame massive en lave durcie. Lente mais dévastatrice.', rarity: ItemRarity.RARE, type: ItemType.WEAPON, icon: 'item_magma_greatsword', value: 380, element: ElementType.FIRE, weaponType: WeaponType.GREATSWORD, damage: 43, magicDamage: 19, bonusStats: {}, attackSpeed: 0.7, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 33, max: 52 }, substats: [{ key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }] } },
  { id: 'colossus_greatsword', lore: 'Le colosse s\'est effondré sans la lâcher. Les mineurs de Deepdelve ont essayé les leviers, puis les palans, puis les prières. Rien n\'a bougé. Il a fallu attendre trois saisons que la pierre oublie pourquoi elle la tenait — la mémoire de Gorvun s\'efface lentement, mais elle s\'efface. Un matin, les doigts se sont ouverts d\'eux-mêmes.', name: 'Espadon du Colosse', description: 'Arraché à un Colosse des Ruines. Pèse autant qu\'un cheval.', rarity: ItemRarity.EPIC, type: ItemType.WEAPON, icon: 'item_colossus_greatsword', value: 1200, element: ElementType.EARTH, weaponType: WeaponType.GREATSWORD, damage: 55, magicDamage: 25, bonusStats: {}, attackSpeed: 0.65, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 43, max: 67 }, substats: [{ key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'HP_FLAT', min: 42, max: 66 }] } },
  { id: 'titan_greatsword', lore: 'Les titans de Glaciem sont tombés bien avant Crysthea, et la glace les garde comme elle garde tout : entiers, patients, presque prêts. Les tailleurs de Frostveil n\'ont jamais dégagé celui-ci en entier — seulement le bras, et l\'espadon avec. Le froid qu\'il dégage n\'est pas celui de la glace. C\'est le sien. Certains porteurs disent sentir le titan finir leurs gestes à leur place, toujours un peu plus bas, toujours un peu plus fort.', name: 'Espadon du Titan', description: 'Des titans gelés de Glaciem. Pulse d\'un froid intense.', rarity: ItemRarity.LEGENDARY, type: ItemType.WEAPON, icon: 'item_titan_greatsword', value: 5000, element: ElementType.ICE, weaponType: WeaponType.GREATSWORD, damage: 71, magicDamage: 32, bonusStats: {}, attackSpeed: 0.6, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 55, max: 86 }, substats: [{ key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 2, max: 3, isPercentage: true }, { key: 'SPD_FLAT', min: 4, max: 7 }] } },
  { id: 'fire_staff', lore: 'Les prêtres de Pyrath en donnaient aux pèlerins pour la traversée des champs de cendre. La flamme ne devait servir qu\'à éclairer — c\'était gravé sur le manche, dans une écriture de culte que plus personne ne lit. Depuis que les prêtres ne sont plus là, personne ne fait respecter la règle. Le sceptre, lui, brûle pareil.', name: 'Sceptre de Braise', description: 'Un sceptre qui canalise la magie du feu.', rarity: ItemRarity.UNCOMMON, type: ItemType.WEAPON, icon: 'item_fire_staff', value: 120, element: ElementType.FIRE, weaponType: WeaponType.STAFF, damage: 15, magicDamage: 34, bonusStats: {}, attackSpeed: 0.85, equipRanges: { mainStat: { key: 'MATK_FLAT', min: 26, max: 41 }, substats: [{ key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }] } },
  { id: 'leviathan_staff', name: 'Sceptre du Léviathan', description: 'Sculpté dans un os de la forme antique de Thalymor. Imprégné de magie océanique.', rarity: ItemRarity.EPIC, type: ItemType.WEAPON, icon: 'item_leviathan_staff', value: 1200, element: ElementType.WATER, weaponType: WeaponType.STAFF, damage: 25, magicDamage: 55, bonusStats: {}, attackSpeed: 0.9, lore: 'Thalymor perdait des os comme la mer perd de l\'écume — sans y penser, sans les compter. Celui-ci s\'est échoué il y a quatre cents ans sur la grève de Saltmourn, et le village a bâti un abri autour plutôt que de le déplacer. Quand les sculpteurs l\'ont enfin taillé, l\'os était encore humide au cœur. Il l\'est toujours. La mer ne rend jamais rien complètement.', equipRanges: { mainStat: { key: 'MATK_FLAT', min: 43, max: 67 }, substats: [{ key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'MATK_PCT', min: 13, max: 21, isPercentage: true }, { key: 'HP_FLAT', min: 42, max: 66 }] } },
  { id: 'memory_staff', name: 'Sceptre des Souvenirs', description: 'Chaque frappe ralentit la cible tandis que ses souvenirs refont surface.', rarity: ItemRarity.LEGENDARY, type: ItemType.WEAPON, icon: 'item_memory_staff', value: 5000, element: ElementType.ICE, weaponType: WeaponType.STAFF, damage: 32, magicDamage: 71, bonusStats: {}, attackSpeed: 0.95, lore: 'Crysthea préservait les souvenirs — c\'était sa charge, et elle la portait sans se plaindre. Les mourants de Frostveil montaient jusqu\'à ses archives pour lui confier un visage, une voix, un nom, et redescendaient plus légers. Ce sceptre appartenait aux archives. Il fait encore son travail : ceux qu\'il touche ralentissent, saisis par quelque chose qu\'ils croyaient enterré. La déesse s\'efface. Sa charge, non.', equipRanges: { mainStat: { key: 'MATK_FLAT', min: 55, max: 86 }, substats: [{ key: 'LIFESTEAL_PCT', min: 2, max: 3, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'MATK_PCT', min: 13, max: 21, isPercentage: true }, { key: 'SPD_FLAT', min: 4, max: 7 }] } },
  { id: 'crystal_dragon_fang_staff', lore: 'Les dragons de cristal de Glaciem ne meurent pas comme les autres bêtes — ils s\'arrêtent, simplement, et le froid fait le reste. Cette dent s\'est brisée il y a des siècles contre quelque chose dont on n\'a jamais rien retrouvé. Elle n\'a jamais tiédi. Certaines choses de Glaciem refusent de finir ; à Frostveil, on apprend tôt à respecter ça.', name: 'Sceptre-Croc de Cristal', description: 'Taillé dans la dent brisée d\'un dragon de cristal. Froid et tranchant.', rarity: ItemRarity.EPIC, type: ItemType.WEAPON, icon: 'item_crystal_staff', value: 1200, element: ElementType.ICE, weaponType: WeaponType.STAFF, damage: 25, magicDamage: 55, bonusStats: {}, attackSpeed: 1.0, equipRanges: { mainStat: { key: 'MATK_FLAT', min: 43, max: 67 }, substats: [{ key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'herald_staff', lore: 'Les ingénieurs de Volterra ont mis douze ans à le concevoir : un conducteur assez pur pour porter une voix humaine jusqu\'au cœur de la tempête. Ils voulaient parler à Volkran d\'égal à égal — pas le prier, discuter. Le jour de l\'essai, le réseau entier s\'est tu pendant quatre secondes. Puis la tempête a repris, exactement comme avant. Le dieu n\'a jamais répondu ; certains ingénieurs soutiennent encore qu\'il a écouté.', name: 'Conducteur du Héraut', description: 'Conçu par les ingénieurs de Volterra pour canaliser Volkran directement.', rarity: ItemRarity.EPIC, type: ItemType.WEAPON, icon: 'item_herald_staff', value: 1200, element: ElementType.LIGHTNING, weaponType: WeaponType.STAFF, damage: 25, magicDamage: 55, bonusStats: {}, attackSpeed: 0.92, equipRanges: { mainStat: { key: 'MATK_FLAT', min: 43, max: 67 }, substats: [{ key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'HP_FLAT', min: 42, max: 66 }] } },
  { id: 'malachars_staff', name: 'Sceptre de Malachar', description: 'Le sceptre qui a lancé la Malédiction du Délitement. Il vibre du souvenir de chaque puissance élémentaire.', rarity: ItemRarity.MYTHIC, type: ItemType.WEAPON, icon: 'item_malachars_staff', value: 12000, element: ElementType.DARK, weaponType: WeaponType.STAFF, damage: 41, magicDamage: 91, bonusStats: {}, attackSpeed: 1.1, lore: 'Malachar l\'a taillé lui-même, la première année de la tour, dans un bois qui ne pousse nulle part à Velmara. Il l\'a porté trente ans — pour marcher, pour écrire, pour tenir debout quand les nuits de calcul duraient trop. Le bois est poli à la hauteur exacte de sa main, et nulle part ailleurs. C\'est avec lui qu\'il a prononcé la Malédiction du Délitement, un matin, sans cérémonie. Il ne l\'a jamais posé. Pas une seule fois.', equipRanges: { mainStat: { key: 'MATK_FLAT', min: 71, max: 110 }, substats: [{ key: 'MATK_PCT', min: 13, max: 21, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 2, max: 3, isPercentage: true }, { key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }] } },
  { id: 'harpy_bow', lore: 'Les harpies de Zephyr Peaks escortaient les voyageurs égarés, autrefois — elles volaient bas, à portée de voix, jusqu\'au prochain refuge. Cet arc est fait de ce qu\'elles ont laissé tomber en chemin : plumes, tendons, un os creux pour la poignée. Le facteur d\'arcs de Windherald n\'a rien pris qu\'elles n\'aient donné. Ça se sent à la détente, disent les archers. L\'arc ne force jamais.', name: 'Arc des Harpies', description: 'Léger comme une plume, précis dans le vent.', rarity: ItemRarity.UNCOMMON, type: ItemType.WEAPON, icon: 'item_harpy_bow', value: 120, element: ElementType.WIND, weaponType: WeaponType.BOW, damage: 20, magicDamage: 9, bonusStats: {}, attackSpeed: 1.3, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 15, max: 24 }, substats: [{ key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'sky_titan_bow', lore: 'Un titan du ciel l\'a bandé une seule fois, dit-on, du temps où les îles de Zephyr Peaks tenaient encore ensemble. Le trait n\'est jamais retombé. Les bergers d\'altitude racontent qu\'il monte toujours, quelque part au-dessus des nuages, et que Sylvael le regardait passer chaque année à la même date. Personne d\'assez fort pour bander l\'arc n\'a confirmé l\'histoire. Personne n\'est redescendu la démentir non plus.', name: 'Arc du Titan Céleste', description: 'Si grand qu\'il exige une force inhumaine. Tire des projectiles d\'air comprimé.', rarity: ItemRarity.EPIC, type: ItemType.WEAPON, icon: 'item_sky_bow', value: 1200, element: ElementType.WIND, weaponType: WeaponType.BOW, damage: 33, magicDamage: 15, bonusStats: {}, attackSpeed: 0.8, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 25, max: 40 }, substats: [{ key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }] } },
  { id: 'phoenix_bow', name: 'Arc du Phénix', description: 'Fait des plumes de Sylvael. Les flèches s\'enflamment au départ.', rarity: ItemRarity.LEGENDARY, type: ItemType.WEAPON, icon: 'item_phoenix_bow', value: 5000, element: ElementType.WIND, weaponType: WeaponType.BOW, damage: 42, magicDamage: 19, bonusStats: {}, attackSpeed: 1.1, lore: 'Sylvael ne perdait jamais une plume par accident. Chaque plume était délibérée — posée sur un seuil, glissée dans un berceau, laissée sur une tombe fraîche. À Windherald, on les gardait sans jamais les vendre. Celles de cet arc ont été réunies une à une, sur trois générations, par une famille qui n\'a jamais voulu dire pourquoi. À quelle fin la déesse les semait, nul ne le sait. Peut-être pour qu\'il reste quelque chose d\'elle qui vole.', equipRanges: { mainStat: { key: 'ATK_FLAT', min: 33, max: 51 }, substats: [{ key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 2, max: 3, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }] } },
  { id: 'dagger_of_shadow', lore: 'Elle a changé de mains plus souvent qu\'aucune autre lame de Velmara — rarement de gré. On la retrouve dans les inventaires de succession, les fouilles de cadavres, les caches sous les lattes des planchers. Un receleur de Grievy Town tient la liste de ses propriétaires connus ; il s\'arrête toujours de compter au même endroit. Ce n\'est pas la lame qui porte malheur, dit-il. C\'est ce que les gens acceptent de faire pour l\'avoir.', name: 'Dague de l\'Ombre', description: 'Difficile à voir venir. Inflige des dégâts supplémentaires dans le dos.', rarity: ItemRarity.RARE, type: ItemType.WEAPON, icon: 'item_shadow_dagger', value: 380, weaponType: WeaponType.DAGGER, damage: 22, magicDamage: 10, bonusStats: {}, attackSpeed: 1.6, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 17, max: 26 }, substats: [{ key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }] } },
  { id: 'depth_serpent_fang_dagger', lore: 'Les serpents des abysses chassent sous la ligne où la lumière renonce. La dent est creuse, comme toutes celles de l\'espèce — un canal pour quelque chose que les pêcheurs de Saltmourn préfèrent ne pas nommer. Ce qu\'elle contenait s\'est vidé depuis longtemps ; c\'est du moins ce qu\'on espère. Elle dégoutte encore aux heures des anciennes marées. Il n\'y a plus de marées.', name: 'Croc des Profondeurs', description: 'Taillée dans la dent creuse d\'un serpent des abysses. Dégoutte encore.', rarity: ItemRarity.RARE, type: ItemType.WEAPON, icon: 'item_depth_fang', value: 380, element: ElementType.WATER, weaponType: WeaponType.DAGGER, damage: 22, magicDamage: 10, bonusStats: {}, attackSpeed: 1.5, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 17, max: 26 }, substats: [{ key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }] } },
  { id: 'malachar_blade', lore: 'Il s\'en servait pour tailler ses plumes d\'écriture. Trente ans de notes, de schémas, de preuves recopiées trois fois — tout a commencé par ce canif. La lame est usée d\'un seul côté, celui d\'un homme méthodique qui répète le même geste sans y penser. Rien d\'ornemental, rien de cruel. C\'est peut-être ça, le plus difficile à regarder.', name: 'Canif de Malachar', description: 'Sa lame personnelle. Rien d\'ornemental — juste fonctionnel. Comme l\'homme lui-même.', rarity: ItemRarity.EPIC, type: ItemType.WEAPON, icon: 'item_malachar_blade', value: 1200, element: ElementType.DARK, weaponType: WeaponType.DAGGER, damage: 28, magicDamage: 13, bonusStats: {}, attackSpeed: 1.8, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 22, max: 34 }, substats: [{ key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'HP_FLAT', min: 42, max: 66 }] } },
  { id: 'gorvun_hammer', lore: 'Gorvun ne perdait rien — c\'était sa nature. Les montagnes de Terravast tenaient parce qu\'il les tenait ; les mineurs de Deepdelve creusaient sous sa patience comme des enfants jouent sous une table. Ce fragment s\'est détaché de lui, et la terre entière a tressailli. Aiguisé, il coupe comme coupe l\'éboulement : sans colère, sans retour. C\'est la preuve que la nature a cédé. Il n\'y en aura pas d\'autre.', name: 'Fragment-Lame de Gorvun', description: 'Un éclat du corps de Gorvun, aiguisé en lame massive.', rarity: ItemRarity.LEGENDARY, type: ItemType.WEAPON, icon: 'item_gorvun_hammer', value: 5000, element: ElementType.EARTH, weaponType: WeaponType.GREATSWORD, damage: 71, magicDamage: 32, bonusStats: {}, attackSpeed: 0.55, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 55, max: 86 }, substats: [{ key: 'LIFESTEAL_PCT', min: 2, max: 3, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'SPD_FLAT', min: 4, max: 7 }] } },
  { id: 'volkran_hammer', lore: 'Volkran vivait dans le réseau de Volterra comme le sang vit dans un corps — les ingénieurs mesuraient son humeur aux fluctuations du courant, et le courant n\'a jamais menti. Ceci était son centre. Il se décharge encore, à intervalles réguliers, soixante fois par minute exactement. Pas comme une machine. Comme un cœur qui n\'a pas compris que c\'était fini.', name: 'Cœur de Volkran', description: 'Le cœur du corps de Volkran, façonné en arme. En décharge constante.', rarity: ItemRarity.LEGENDARY, type: ItemType.WEAPON, icon: 'item_volkran_hammer', value: 5000, element: ElementType.LIGHTNING, weaponType: WeaponType.GREATSWORD, damage: 71, magicDamage: 32, bonusStats: {}, attackSpeed: 0.75, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 55, max: 86 }, substats: [{ key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'sentinel_sword', lore: 'Forgée dans la Spire par le plus dévoué des serviteurs de Malachar, pour un maître qui ne demandait rien. Malachar ne l\'a jamais portée ; il ne portait pas d\'armes. Le Sentinelle l\'a donc portée pour lui, trente ans, devant une porte que personne ne venait jamais franchir. La dévotion pèse plus lourd que l\'acier. Cette lame porte le poids des deux.', name: 'Lame du Sentinelle', description: 'Sombre et lourde. Forgée par le serviteur le plus dévoué de Malachar.', rarity: ItemRarity.EPIC, type: ItemType.WEAPON, icon: 'item_sentinel_sword', value: 1200, element: ElementType.DARK, weaponType: WeaponType.SWORD, damage: 36, magicDamage: 16, bonusStats: {}, attackSpeed: 0.95, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 28, max: 43 }, substats: [{ key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }] } },
  { id: 'drowned_knight_sword', lore: 'Un chevalier d\'un ordre oublié est descendu dans Abyssmar quand la ville a coulé — pour sauver qui, les registres ne le disent plus. Il la tenait encore quand les plongeurs de Saltmourn l\'ont remonté, quarante ans plus tard. Il a fallu choisir entre la lame et les doigts. Les plongeurs n\'en parlent pas, mais depuis, ils saluent la mer avant chaque descente.', name: 'Épée du Chevalier Noyé', description: 'Lame récupérée sur un chevalier perdu dans les profondeurs d\'Abyssmar.', rarity: ItemRarity.RARE, type: ItemType.WEAPON, icon: 'item_drowned_sword', value: 380, element: ElementType.WATER, weaponType: WeaponType.SWORD, damage: 28, magicDamage: 13, bonusStats: {}, attackSpeed: 1.0, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 22, max: 34 }, substats: [{ key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }] } },
];

// ── ARMOR ──────────────────────────────────────────────────────

export const ARMORS: Armor[] = [
  // Helms
  { id: 'leather_helm', lore: 'Cousu à Grievy Town, dans l\'atelier derrière la place du marché. Le tanneur en fait trois par semaine, toujours du même patron — celui de son père. Quand un heaume revient cabossé, il le rachète, le retape et ne pose pas de questions. C\'est sa façon à lui de suivre les nouvelles.', name: 'Heaume de Cuir', description: 'Protection basique pour la tête.', rarity: ItemRarity.COMMON, type: ItemType.HELM, icon: 'item_leather_helm', value: 40, defense: 3, magicDefense: 2, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 33, max: 52 }, substats: [{ key: 'DODGE_PCT', min: 4, max: 7, isPercentage: true }] } },
  { id: 'iron_helm', lore: 'Le modèle n\'a pas changé depuis trois générations — même visière courte, mêmes rivets, même doublure de feutre. Le forgeron de Grievy Town dit qu\'on n\'améliore pas ce qui ramène les gens. Les têtes qu\'il protège, elles, ont changé. Elles partent plus jeunes, et reviennent moins souvent.', name: 'Heaume de Fer', description: 'Casque en fer standard.', rarity: ItemRarity.UNCOMMON, type: ItemType.HELM, icon: 'item_iron_helm', value: 120, defense: 3, magicDefense: 2, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 43, max: 67 }, substats: [{ key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'titan_helm', name: 'Heaume du Titan Magma', description: 'Sculpté dans le crâne d\'un Titan de Magma. Extrêmement chaud à porter.', rarity: ItemRarity.RARE, type: ItemType.HELM, icon: 'item_titan_helm', value: 380, element: ElementType.FIRE, defense: 4, magicDefense: 3, bonusStats: {}, lore: 'Les Titans de Magma marchaient dans Ignis Reach avant les premiers temples de Pyrath. Celui-ci est tombé face contre terre et la lave l\'a pris en entier ; seul le crâne dépassait. Les orbites sont restées vides quand on l\'a taillé en heaume. Ceux qui l\'ont porté disent qu\'elles regardent quand même — pas le porteur. Autre chose, plus loin.', equipRanges: { mainStat: { key: 'HP_FLAT', min: 56, max: 87 }, substats: [{ key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'HP_ON_KILL_FLAT', min: 9, max: 14 }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }] } },
  { id: 'leather_chest', lore: 'Il sent le cuir, la fumée et la route. L\'odeur ne part jamais tout à fait, même après des semaines pendues dans une grange. Le tanneur de Grievy Town dit qu\'un plastron qui ne sent rien n\'a encore protégé personne. Celui-ci sent comme tous ceux qui le portent.', name: 'Plastron de Cuir', description: 'Protection basique pour le torse.', rarity: ItemRarity.COMMON, type: ItemType.CHEST, icon: 'item_leather_chest', value: 40, defense: 4, magicDefense: 3, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 48, max: 75 }, substats: [{ key: 'HP_ON_KILL_FLAT', min: 4, max: 6 }] } },
  { id: 'iron_chest', lore: 'Standard de l\'ancienne milice de Grievy Town, matricule frappé sous le col. La milice a été dissoute faute d\'hommes, bien avant la Malédiction — plus personne ne se souvient de ce qu\'elle guettait. Les plastrons circulent encore, de main en main, de foire en foire. Certains portent deux ou trois matricules limés.', name: 'Plastron de Fer', description: 'Plastron en fer standard.', rarity: ItemRarity.UNCOMMON, type: ItemType.CHEST, icon: 'item_iron_chest', value: 120, defense: 5, magicDefense: 4, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 62, max: 97 }, substats: [{ key: 'HP_ON_KILL_FLAT', min: 6, max: 9 }, { key: 'HP_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'fire_chest', lore: 'L\'obsidienne d\'Ignis Reach se souvient de la coulée qui l\'a faite ; rien de plus chaud ne l\'inquiète. Les forgerons d\'Ashford la travaillent à froid, au burin, en silence — le verre volcanique n\'aime pas qu\'on le presse. Une cuirasse demande six mois. On en refuse plus qu\'on n\'en vend.', name: 'Cuirasse d\'Ignis', description: 'Forgée dans l\'obsidienne d\'Ignis Reach. Résiste au feu.', rarity: ItemRarity.RARE, type: ItemType.CHEST, icon: 'item_fire_chest', value: 380, element: ElementType.FIRE, defense: 6, magicDefense: 5, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 80, max: 126 }, substats: [{ key: 'HP_ON_KILL_FLAT', min: 9, max: 14 }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'SPD_FLAT', min: 4, max: 7 }] } },
  { id: 'crystal_chest', lore: 'Le cristal de Terravast ne se raye pas. Il garde pourtant la trace de chaque coup, quelque part à l\'intérieur — de petites fleurs de lumière figées dans la masse. Les mineurs de Deepdelve lisent une cuirasse comme on lit un journal : ici une lame, là une chute, là quelque chose de plus gros. Aucune ne s\'est jamais brisée. Elles se contentent de retenir.', name: 'Cuirasse de Cristal', description: 'Cristal de Terravast. Extrêmement dur.', rarity: ItemRarity.RARE, type: ItemType.CHEST, icon: 'item_crystal_chest', value: 380, element: ElementType.EARTH, defense: 6, magicDefense: 5, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 80, max: 126 }, substats: [{ key: 'HP_ON_KILL_FLAT', min: 9, max: 14 }, { key: 'DEF_FLAT', min: 8, max: 12 }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }] } },
  { id: 'coral_chest', lore: 'Le corail était vivant quand on l\'a taillé — il n\'y a pas d\'autre façon, le corail mort devient cassant comme la craie. Les artisans de Saltmourn jurent qu\'il l\'est encore un peu : la plaque se resserre doucement sur les épaules avec les années, jamais trop. Ils appellent ça s\'apprivoiser. Ils rendent l\'argent quand ça n\'arrive pas.', name: 'Cuirasse de Corail', description: 'Plaque de corail d\'Abyssmar. Légère et résistante à la magie d\'eau.', rarity: ItemRarity.RARE, type: ItemType.CHEST, icon: 'item_coral_chest', value: 380, element: ElementType.WATER, defense: 6, magicDefense: 5, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 80, max: 126 }, substats: [{ key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'HP_ON_KILL_FLAT', min: 9, max: 14 }, { key: 'SPD_FLAT', min: 4, max: 7 }] } },
  { id: 'pyrath_armor', lore: 'Pyrath réchauffait tout ce qu\'il touchait. Les pèlerins montaient à Ignis Reach juste pour ça — poser une main sur une écaille, et redescendre avec un peu de chaleur pour l\'hiver. Cette section s\'est détachée de lui sans qu\'aucune forge y soit pour rien ; elle est née armure comme lui était né dieu. Elle est tiède, des siècles après. Elle le restera plus longtemps qu\'il ne restera quelqu\'un pour s\'en souvenir.', name: 'Cuirasse d\'Écailles de Pyrath', description: 'Une section des écailles divines de Pyrath. Aucune forge ne l\'a faite — elle est née.', rarity: ItemRarity.LEGENDARY, type: ItemType.CHEST, icon: 'item_pyrath_armor', value: 5000, element: ElementType.FIRE, defense: 8, magicDefense: 6, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 135, max: 212 }, substats: [{ key: 'DEF_FLAT', min: 10, max: 15 }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'DODGE_PCT', min: 4, max: 7, isPercentage: true }, { key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }] } },
  { id: 'titan_earth_armor', lore: 'Gorvun avait promis de ne pas bouger — c\'est la seule promesse qu\'on lui connaisse, et Terravast entière reposait dessus. Les cavernes tenaient, les villages dormaient, les mineurs de Deepdelve chantaient dans le noir sans y penser. Puis la Malédiction est passée, et le dieu s\'est levé. Ce morceau de sa surface pèse plus qu\'il ne devrait. C\'est le poids d\'une parole tenue.', name: 'Cuirasse-Fragment de Gorvun', description: 'Un morceau de la surface de Gorvun, façonné en armure. D\'une lourdeur impossible.', rarity: ItemRarity.LEGENDARY, type: ItemType.CHEST, icon: 'item_earth_armor', value: 5000, element: ElementType.EARTH, defense: 8, magicDefense: 6, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 135, max: 212 }, substats: [{ key: 'HP_ON_KILL_FLAT', min: 19, max: 30 }, { key: 'DEF_FLAT', min: 10, max: 15 }, { key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ATK_FLAT', min: 7, max: 11 }] } },
  { id: 'abyssal_chest', lore: 'Forgé sous l\'eau, dans les fosses d\'Abyssmar, à des pressions qu\'aucun poumon ne supporte. Du corail le plus profond, des écailles de Thalymor, et des mains dont Saltmourn ne parle qu\'à voix basse. Un plastron comme celui-ci remonte à la surface une fois par génération — toujours vide, toujours fini. Personne ne demande comment. Quelqu\'un a demandé, une fois ; la mer a gardé la question.', name: 'Plastron Abyssal', description: 'Forgé du corail le plus profond et des écailles de Thalymor. Lourd comme le fond de l\'océan.', rarity: ItemRarity.LEGENDARY, type: ItemType.CHEST, icon: 'item_abyssal_chest', value: 5000, element: ElementType.WATER, defense: 8, magicDefense: 6, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 135, max: 212 }, substats: [{ key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 2, max: 3, isPercentage: true }, { key: 'SPD_FLAT', min: 4, max: 7 }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'HP_ON_KILL_FLAT', min: 19, max: 30 }] } },
  { id: 'storm_plate', lore: 'Les ingénieurs de Volterra le portaient pour approcher Volkran les jours de maintenance du réseau. Le métal rend la foudre au premier coup reçu, sans qu\'on le lui demande — le dieu prenait ça pour de la politesse, une façon de parler sa langue. Il répondait par de petites décharges précises, jamais mortelles. Les ingénieurs appelaient ça la conversation. Il n\'y a plus personne au bout de la ligne, mais le plastron continue de répondre.', name: 'Plastron de Tempête de Volkran', description: 'Armure conductrice. Se décharge électriquement à chaque coup reçu.', rarity: ItemRarity.LEGENDARY, type: ItemType.CHEST, icon: 'item_storm_plate', value: 5000, element: ElementType.LIGHTNING, defense: 8, magicDefense: 6, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 135, max: 212 }, substats: [{ key: 'DEF_FLAT', min: 10, max: 15 }, { key: 'SPD_FLAT', min: 4, max: 7 }, { key: 'LIFESTEAL_PCT', min: 2, max: 3, isPercentage: true }, { key: 'HP_ON_KILL_FLAT', min: 19, max: 30 }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'glaciem_guardian_chest', lore: 'La glace de Crysthea préserve ce qu\'elle enferme — c\'était sa manière d\'aimer, disent les anciens de Frostveil. Les gardiens de ses archives portaient des cuirasses comme celle-ci, taillées par la déesse elle-même dans la glace qui ne fond pas. Aucun gardien n\'est mort en service. Aucun n\'a vieilli non plus. Porter cette cuirasse, c\'est accepter d\'être gardé ; peu de gens mesurent ce que le mot veut dire.', name: 'Cuirasse de Glaciem', description: 'Une glace si froide qu\'elle gèle les coups qui l\'atteignent.', rarity: ItemRarity.LEGENDARY, type: ItemType.CHEST, icon: 'item_glaciem_chest', value: 5000, element: ElementType.ICE, defense: 8, magicDefense: 6, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 135, max: 212 }, substats: [{ key: 'HP_ON_KILL_FLAT', min: 19, max: 30 }, { key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'DEF_FLAT', min: 10, max: 15 }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'sentinel_armor', lore: 'Le Sentinelle du Vide n\'a jamais parlé — pas une fois en trente ans de garde. Malachar ne lui a jamais donné d\'ordre non plus ; la présence suffisait, dans les deux sens. Cette armure a été forgée pour ce silence-là. Elle absorbe la magie comme son porteur absorbait les ordres qu\'on ne donnait pas : entièrement, sans jamais rien rendre.', name: 'Plastron du Sentinelle du Vide', description: 'Armure sombre qui absorbe les attaques magiques et en convertit une partie en mana.', rarity: ItemRarity.EPIC, type: ItemType.CHEST, icon: 'item_sentinel_armor', value: 1200, element: ElementType.DARK, defense: 7, magicDefense: 6, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 104, max: 163 }, substats: [{ key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'HP_ON_KILL_FLAT', min: 13, max: 20 }, { key: 'DODGE_PCT', min: 4, max: 7, isPercentage: true }, { key: 'ATK_FLAT', min: 6, max: 9 }] } },
  { id: 'permafrost_armor', lore: 'La glace de titan garde le geste de celui qu\'elle a pris. Les tailleurs de Frostveil découpent leurs plaques loin du cœur des blocs, par précaution — mais le froid circule, et le geste avec. Quelque chose court encore à l\'intérieur de cette armure, un mouvement lent, jamais achevé. Les porteurs s\'y font. Ils disent que c\'est comme être deux à veiller.', name: 'Armure de Permafrost', description: 'Armure en glace de titan. Émet un froid qui blesse les ennemis proches.', rarity: ItemRarity.EPIC, type: ItemType.CHEST, icon: 'item_permafrost_armor', value: 1200, element: ElementType.ICE, defense: 7, magicDefense: 6, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 104, max: 163 }, substats: [{ key: 'HP_ON_KILL_FLAT', min: 13, max: 20 }, { key: 'DEF_FLAT', min: 9, max: 13 }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'ATK_FLAT', min: 6, max: 9 }] } },
  { id: 'storm_herald_plate', lore: 'Le Héraut devait être le premier homme à entrer dans l\'œil de la tempête de Volterra — un volontaire, choisi sur concours, préparé pendant deux ans. Le plastron a été conçu pour une conductivité parfaite, pour un porteur qui ne craindrait rien. Les ingénieurs l\'ont fait beau quand même : gravures, filets de cuivre, doublure de soie. La mission a été annulée quand Volkran a changé. Le plastron, lui, était prêt.', name: 'Plastron du Héraut', description: 'Conçu pour une conductivité maximale.', rarity: ItemRarity.EPIC, type: ItemType.CHEST, icon: 'item_herald_plate', value: 1200, element: ElementType.LIGHTNING, defense: 7, magicDefense: 6, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 104, max: 163 }, substats: [{ key: 'HP_ON_KILL_FLAT', min: 13, max: 20 }, { key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'unbound_robe', lore: 'Il l\'a cousue lui-même, la première année de la tour, avec le fil et la toile emportés de Grievy Town. Personne ne coud pour un homme qui vit seul. Les reprises se comptent aux coudes — trente hivers, trente épaisseurs, un travail de moins en moins soigné à mesure que la recherche prenait la place du reste. Elle résonne des six éléments, maintenant, comme tout ce qui l\'a approché trop longtemps. Elle a tenu trente ans. Lui aussi.', name: 'Robe de Malachar', description: 'La robe de l\'homme qui a brisé le monde. Résonne encore avec les six éléments.', rarity: ItemRarity.MYTHIC, type: ItemType.CHEST, icon: 'item_unbound_robe', value: 12000, defense: 9, magicDefense: 7, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 176, max: 275 }, substats: [{ key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'DODGE_PCT', min: 4, max: 7, isPercentage: true }, { key: 'HP_ON_KILL_FLAT', min: 27, max: 43 }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 2, max: 3, isPercentage: true }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'pilgrim_robe', lore: 'Quelqu\'un est venu à Ignis Reach pour guérir — les sources chaudes, disait-on alors, ou la bénédiction de Pyrath, ou juste l\'espoir. L\'ourlet est usé dans le sens de la montée, effiloché par la roche et la cendre. Il n\'y a pas d\'usure pour la descente.', name: 'Robe du Pèlerin', description: 'Une robe portée par quelqu\'un venu à Ignis Reach pour guérir. Il ne l\'a pas trouvé.', rarity: ItemRarity.UNCOMMON, type: ItemType.CHEST, icon: 'item_pilgrim_robe', value: 120, defense: 5, magicDefense: 4, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 62, max: 97 }, substats: [{ key: 'DEF_FLAT', min: 7, max: 11 }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'ice_dragon_scale_chest', lore: 'Les dragons de cristal muent une écaille à la fois, sur des siècles. Quelqu\'un a pris le temps de toutes les ramasser — un ermite de Glaciem, disent les archives de Frostveil, qui suivait le même dragon depuis l\'enfance et le reconnaissait à son pas. L\'armure a été finie l\'hiver de sa mort. Le registre ne précise pas s\'il parlait de la sienne ou de celle du dragon ; la phrase s\'arrête là.', name: 'Cuirasse d\'Écailles de Dragon', description: 'Écailles de dragon de cristal superposées en armure. Réfléchit la magie de glace.', rarity: ItemRarity.EPIC, type: ItemType.CHEST, icon: 'item_dragon_chest', value: 1200, element: ElementType.ICE, defense: 7, magicDefense: 6, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 104, max: 163 }, substats: [{ key: 'DEF_FLAT', min: 9, max: 13 }, { key: 'HP_ON_KILL_FLAT', min: 13, max: 20 }, { key: 'SPD_FLAT', min: 4, max: 7 }, { key: 'ATK_FLAT', min: 6, max: 9 }] } },
  { id: 'runic_armor', lore: 'Les plaques viennent des profondeurs de Terravast, gravées bien avant que Deepdelve n\'existe. Les runes forment une phrase de Gorvun que nul ne sait plus lire — Ovan y a passé des semaines et n\'a traduit qu\'un seul mot : rester. Elle protège quand même. Les mots des dieux n\'ont jamais eu besoin qu\'on les comprenne.', name: 'Armure Runique', description: 'Plaques gravées de runes des profondeurs de Terravast.', rarity: ItemRarity.RARE, type: ItemType.CHEST, icon: 'item_runic_armor', value: 380, element: ElementType.EARTH, defense: 6, magicDefense: 5, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 80, max: 126 }, substats: [{ key: 'HP_ON_KILL_FLAT', min: 9, max: 14 }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'SPD_FLAT', min: 4, max: 7 }] } },
  { id: 'seaguard_armor', lore: 'La garnison des Gardes-Mer a coulé avec la ville, une nuit, sans qu\'aucune cloche ne sonne à Saltmourn. Les plastrons remontent, parfois, quand les courants changent — le corail a poussé par-dessus le fer, comme si la mer les avait entretenus. Les gardes, jamais. On repeint le blason avant chaque revente. Il transparaît toujours.', name: 'Armure des Gardes-Mer', description: 'Plastron renforcé de corail de la garnison noyée.', rarity: ItemRarity.UNCOMMON, type: ItemType.CHEST, icon: 'item_seaguard_armor', value: 120, element: ElementType.WATER, defense: 5, magicDefense: 4, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 62, max: 97 }, substats: [{ key: 'HP_ON_KILL_FLAT', min: 6, max: 9 }, { key: 'SPD_FLAT', min: 4, max: 7 }] } },
  { id: 'glacial_shield', lore: 'Formé de la glace ancienne de Glaciem, celle des couches d\'avant les titans — elle ne fond pas ; elle ne sait probablement plus ce que c\'est. Il a arrêté un coup de fléau de Crysthea, dit-on à Frostveil, dans les premiers jours de son changement. Du bras qui le tenait, on ne dit rien. Le bouclier, lui, n\'a pas une fissure.', name: 'Bouclier Glacial', description: 'Un bouclier formé de la glace ancienne de Glaciem — ne fond jamais.', rarity: ItemRarity.RARE, type: ItemType.CHEST, icon: 'item_glacial_shield', value: 380, element: ElementType.ICE, defense: 6, magicDefense: 5, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 80, max: 126 }, substats: [{ key: 'HP_ON_KILL_FLAT', min: 9, max: 14 }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'SPD_FLAT', min: 4, max: 7 }] } },
  { id: 'leather_boots', lore: 'Ressemelées trois fois, chez trois cordonniers différents — on peut suivre le fil des réparations comme un itinéraire. Les routes de Velmara usent tout : le cuir, les semelles, les compagnons de départ. Tout, sauf l\'envie de partir.', name: 'Bottes de Cuir', description: 'Protection basique pour les pieds.', rarity: ItemRarity.COMMON, type: ItemType.BOOTS, icon: 'item_leather_boots', value: 40, defense: 2, magicDefense: 2, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 26, max: 40 }, substats: [{ key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'serpent_scale_boots', lore: 'Les écailles viennent d\'un serpent des marées pris dans les filets de Saltmourn — trop grand pour le filet, trop vieux pour se débattre. Elles n\'ont pas oublié la nage. Sur la pierre mouillée, dans les passes inondées d\'Abyssmar, elles retrouvent leurs habitudes et le pied ne glisse jamais. Les pêcheurs disent que c\'est la bête qui continue son chemin.', name: 'Bottes d\'Écailles de Serpent', description: 'Légères, adhérentes et résistantes à l\'eau.', rarity: ItemRarity.RARE, type: ItemType.BOOTS, icon: 'item_serpent_boots', value: 380, defense: 3, magicDefense: 2, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 43, max: 68 }, substats: [{ key: 'SPD_FLAT', min: 4, max: 7 }, { key: 'DODGE_PCT', min: 4, max: 7, isPercentage: true }, { key: 'HP_ON_KILL_FLAT', min: 9, max: 14 }] } },
  { id: 'air_walker_boots', lore: 'Cousues pour les prêtres de Sylvael, qui marchaient d\'île en île sur des ponts de vent que la déesse tendait pour eux. Le silence était une forme de prière : un pas qu\'on n\'entend pas est un pas qui ne demande rien. Les ponts sont tombés avec le reste de Zephyr Peaks. Les bottes, elles, se souviennent de la consigne.', name: 'Bottes du Marcheur des Airs', description: 'Réduisent le son de vos pas au silence.', rarity: ItemRarity.EPIC, type: ItemType.BOOTS, icon: 'item_air_boots', value: 1200, element: ElementType.WIND, defense: 4, magicDefense: 3, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 56, max: 88 }, substats: [{ key: 'DODGE_PCT', min: 4, max: 7, isPercentage: true }, { key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'obsidian_gauntlets', lore: 'Un lutteur d\'Ashford les portait aux tournois d\'avant l\'éruption. Il n\'a jamais perdu — pas par talent, disait-il, par obstination. Après son troisième titre, plus personne ne lui serrait la main. Il les a rendues au forgeron la veille de sa retraite, avec un mot : elles serrent toutes seules, maintenant.', name: 'Gantelets d\'Obsidienne', description: 'Gantelets lourds qui écrasent tout ce qu\'ils saisissent.', rarity: ItemRarity.RARE, type: ItemType.GLOVES, icon: 'item_obsidian_gauntlets', value: 380, element: ElementType.FIRE, defense: 3, magicDefense: 2, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 43, max: 68 }, substats: [{ key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }] } },
  { id: 'storm_eagle_feather_cloak', lore: 'Les aigles des tempêtes nichent au-dessus des dernières îles de Zephyr Peaks, là où l\'air devient trop mince pour les hommes. Les plumes ont été ramassées au sol, une saison après l\'autre, jamais arrachées. La différence se sent dans le vent : une plume donnée porte, une plume prise freine. Les tisserands de Windherald l\'ont appris à leurs dépens.', name: 'Cape de l\'Aigle des Tempêtes', description: 'Réduit le recul des attaques de vent.', rarity: ItemRarity.RARE, type: ItemType.CAPE, icon: 'item_eagle_cloak', value: 380, element: ElementType.WIND, defense: 3, magicDefense: 2, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 43, max: 68 }, substats: [{ key: 'DODGE_PCT', min: 4, max: 7, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'HP_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'tempest_cloak', lore: 'Quand Sylvael a commencé à changer, sa tempête s\'est déchirée sur les crêtes de Zephyr Peaks. Un pan est resté accroché là, tissu et vent à la fois, et une couturière de Windherald a passé un an à comprendre comment le coudre à des épaules humaines. Elle n\'a jamais expliqué sa méthode ; elle disait que la cape avait collaboré. Elle tire vers le ciel, doucement, tout le temps. Comme si elle cherchait à rentrer.', name: 'Cape de la Tempête', description: 'Tissée de la tempête de Sylvael. Vous bougez comme si le vent la portait.', rarity: ItemRarity.LEGENDARY, type: ItemType.CAPE, icon: 'item_tempest_cloak', value: 5000, element: ElementType.WIND, defense: 4, magicDefense: 3, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 73, max: 114 }, substats: [{ key: 'DODGE_PCT', min: 4, max: 7, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'DEF_FLAT', min: 10, max: 15 }, { key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ATK_FLAT', min: 7, max: 11 }] } },
  { id: 'tidal_shell_armor', lore: 'Le rampeur des marées a grandi dedans toute sa vie, agrandissant sa coquille chambre après chambre, année après année. Les artisans de Saltmourn n\'ont fait que sceller l\'ouverture. Elle garde la forme de quelque chose qui ne voulait pas mourir — les stries serrées des mauvaises années, les larges des bonnes. Portée sur le dos, elle continue son seul travail : encaisser, et durer.', name: 'Cape-Coquille des Marées', description: 'La coquille d\'un rampeur des marées transformée en bouclier dorsal.', rarity: ItemRarity.RARE, type: ItemType.CAPE, icon: 'item_tidal_cape', value: 380, element: ElementType.WATER, defense: 3, magicDefense: 2, bonusStats: {}, equipRanges: { mainStat: { key: 'HP_FLAT', min: 43, max: 68 }, substats: [{ key: 'SPD_FLAT', min: 4, max: 7 }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }, { key: 'HP_PCT', min: 5, max: 7, isPercentage: true }] } },
];

// ── ACCESSORIES ────────────────────────────────────────────────

export const ACCESSORIES: Accessory[] = [
  // Rings
  { id: 'flame_ring', lore: 'Les fiancés d\'Ashford s\'en offraient, avant l\'éruption — deux anneaux allumés à la même braise, chez le même artisan, le même jour. La braise tient plus longtemps que la plupart des promesses. L\'artisan tient un registre des paires vendues. Il raye rarement les deux noms en même temps.', name: 'Anneau des Braises', description: 'Dégâts de feu +5%.', rarity: ItemRarity.UNCOMMON, type: ItemType.RING, icon: 'item_flame_ring', value: 120, element: ElementType.FIRE, bonusStats: {}, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 6, max: 9 }, substats: [{ key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'DEF_FLAT', min: 7, max: 11 }] } },
  { id: 'sailor_ghost_ring', lore: 'Un marin de Saltmourn l\'a porté jusqu\'au fond d\'Abyssmar. Le nom gravé à l\'intérieur est rongé par le sel — il reste trois lettres, pas assez pour chercher, trop pour oublier. La femme du port qui rachète ce que la mer rend n\'a jamais voulu de celui-là. Quelqu\'un l\'attend peut-être encore. Elle préfère ne pas savoir qui.', name: 'Anneau du Marin Perdu', description: 'Porté par un marin qui s\'est noyé dans Abyssmar.', rarity: ItemRarity.RARE, type: ItemType.RING, icon: 'item_sailor_ring', value: 380, element: ElementType.WATER, bonusStats: {}, passiveEffect: 'WATER_DMG_15_SPEED_10_PCT', equipRanges: { mainStat: { key: 'ATK_FLAT', min: 8, max: 12 }, substats: [{ key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'revenant_ring', lore: 'Les ouvriers morts sur le réseau de Volterra n\'en partent pas tous. Certains restent ancrés aux lignes, refaisant leur dernière ronde — les ingénieurs les croisaient sans les déranger, par respect ou par prudence. Cet anneau a été retiré à l\'un d\'eux. Le lien n\'a pas été coupé, juste transféré. Le porteur sent parfois qu\'on vérifie son travail.', name: 'Anneau du Revenant Enchaîné', description: 'On se sent lié à lui.', rarity: ItemRarity.RARE, type: ItemType.RING, icon: 'item_revenant_ring', value: 380, element: ElementType.LIGHTNING, bonusStats: {}, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 8, max: 12 }, substats: [{ key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'SPD_FLAT', min: 4, max: 7 }] } },
  { id: 'eternal_flame_ring', lore: 'Chaque temple de Pyrath entretenait un feu sacré ; ils se sont éteints un à un à mesure que le dieu changeait. Cet anneau a été allumé au dernier, par le dernier prêtre, la nuit où il a compris qu\'il ne tiendrait plus. La flamme ne s\'éteint pas. Tant qu\'elle brûle, quelque chose du dieu n\'est pas tout à fait mort — le prêtre appelait ça une veilleuse, pas un espoir. Il tenait à la différence.', name: 'Anneau de la Flamme Éternelle', description: 'La flamme ne s\'éteint jamais. Vous non plus.', rarity: ItemRarity.EPIC, type: ItemType.RING, icon: 'item_eternal_ring', value: 1200, element: ElementType.FIRE, bonusStats: {}, passiveEffect: 'FIRE_SKILL_CD_15_PCT', equipRanges: { mainStat: { key: 'ATK_FLAT', min: 10, max: 15 }, substats: [{ key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'HP_FLAT', min: 42, max: 66 }, { key: 'HP_ON_KILL_FLAT', min: 13, max: 20 }] } },
  { id: 'ring_of_the_wind', lore: 'Forgé dans un temple flottant de Zephyr Peaks, à une altitude où tout pèse moins — le métal, les gestes, les décisions. Les orfèvres de Sylvael travaillaient là-haut pour cette raison. L\'anneau n\'a jamais accepté de redescendre : il garde son poids d\'altitude, où qu\'on le porte. La main suit. Le reste finit par suivre aussi.', name: 'Anneau du Vent', description: 'Du domaine de Sylvael. On se sent plus léger.', rarity: ItemRarity.EPIC, type: ItemType.RING, icon: 'item_wind_ring', value: 1200, element: ElementType.WIND, bonusStats: {}, passiveEffect: 'DASH_DISTANCE_20_PCT', equipRanges: { mainStat: { key: 'ATK_FLAT', min: 10, max: 15 }, substats: [{ key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'HP_FLAT', min: 42, max: 66 }] } },
  { id: 'tidal_ring', lore: 'Thalymor tenait l\'horaire des marées comme un devoir — deux fois par jour, sans un souffle de retard, depuis avant les premiers ports. Les capitaines de Saltmourn réglaient leurs vies dessus. Les marées se sont arrêtées avec le dieu ; l\'anneau, lui, bat encore à son heure. Les vieux marins venaient parfois le tenir, juste pour se rappeler l\'heure qu\'il devrait être. Ils savaient très bien que c\'était autre chose.', name: 'Anneau des Marées', description: 'Pulse comme une marée.', rarity: ItemRarity.EPIC, type: ItemType.RING, icon: 'item_tidal_ring', value: 1200, element: ElementType.WATER, bonusStats: {}, passiveEffect: 'HEAL_SKILL_20_PCT', equipRanges: { mainStat: { key: 'ATK_FLAT', min: 10, max: 15 }, substats: [{ key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'HP_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'eye_of_the_storm_ring', lore: 'Au centre exact de la tempête de Volterra, il y a un endroit calme — quelques mètres où la pluie ne tombe pas, où le tonnerre arrive assourdi comme d\'une pièce voisine. Volkran y rangeait ce qu\'il voulait garder. On n\'a retrouvé que cet anneau, posé au sec au milieu du vacarme du monde. Personne ne sait ce qu\'il y avait d\'autre. Personne ne sait si l\'anneau était gardé, ou gardien.', name: 'Œil de la Tempête', description: 'Vous êtes le centre calme. Tout le reste tourne autour de vous.', rarity: ItemRarity.LEGENDARY, type: ItemType.RING, icon: 'item_storm_ring', value: 5000, element: ElementType.LIGHTNING, bonusStats: {}, passiveEffect: 'LIGHTNING_DMG_STUNNED_20_PCT', equipRanges: { mainStat: { key: 'ATK_FLAT', min: 12, max: 20 }, substats: [{ key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'SPD_FLAT', min: 4, max: 7 }, { key: 'HP_FLAT', min: 56, max: 88 }, { key: 'HP_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'ring_of_preservation', lore: 'Crysthea gardait les visages, les voix, les promesses — tout ce que les gens de Frostveil montaient lui confier avant de mourir. Elle ne refusait rien ; ses archives de glace ont grandi pendant mille ans. Cet anneau est sa nature, concentrée : au bord de la fin, il enveloppe et il retient. Il garde son porteur comme elle gardait les souvenirs. C\'est le même geste. C\'est peut-être tout ce qui en reste.', name: 'Anneau de la Préservation', description: 'La nature de Crysthea, concentrée.', rarity: ItemRarity.LEGENDARY, type: ItemType.RING, icon: 'item_preservation_ring', value: 5000, element: ElementType.ICE, bonusStats: {}, passiveEffect: 'LOW_HP_SHIELD_30_PCT', equipRanges: { mainStat: { key: 'ATK_FLAT', min: 12, max: 20 }, substats: [{ key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'DEF_FLAT', min: 10, max: 15 }, { key: 'DODGE_PCT', min: 4, max: 7, isPercentage: true }] } },
  { id: 'ring_of_the_unbound', lore: 'Il l\'avait déjà au doigt en quittant Grievy Town — un bijou ordinaire, alors. Peut-être un héritage, peut-être un achat de foire ; personne n\'a pensé à le regarder. Trente ans de recherches l\'ont chargé comme la tour elle-même. Il le portait en prononçant la Malédiction du Délitement, et l\'anneau a tout entendu. Il ne l\'a jamais retiré. Pas par attachement — par certitude.', name: 'Anneau du Délié', description: 'L\'anneau de Malachar. Il le portait quand il a lancé la Malédiction du Délitement.', rarity: ItemRarity.MYTHIC, type: ItemType.RING, icon: 'item_unbound_ring', value: 12000, element: ElementType.DARK, bonusStats: {}, passiveEffect: 'SKILL_DMG_15_CD_10_PCT', equipRanges: { mainStat: { key: 'ATK_FLAT', min: 16, max: 25 }, substats: [{ key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }, { key: 'ASPD_PCT', min: 5, max: 7, isPercentage: true }, { key: 'SPD_FLAT', min: 4, max: 7 }, { key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'DODGE_PCT', min: 4, max: 7, isPercentage: true }] } },
  { id: 'shadow_ring', lore: 'Il était froid avant la Spire, froid avant Malachar — le registre d\'un prêteur sur gages de Grievy Town le mentionne trois siècles plus tôt, avec la même remarque agacée. Personne ne sait d\'où lui vient son ombre. Certaines choses n\'ont pas besoin d\'excuse. Le prêteur l\'a revendu à perte, chaque fois.', name: 'Anneau des Ombres', description: 'Froid au toucher. A toujours été froid.', rarity: ItemRarity.RARE, type: ItemType.RING, icon: 'item_shadow_ring', value: 380, element: ElementType.DARK, bonusStats: {}, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 8, max: 12 }, substats: [{ key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'LIFESTEAL_PCT', min: 1, max: 2, isPercentage: true }] } },
  { id: 'wraith_amulet', lore: 'L\'homme hantait les grottes de Terravast de son vivant déjà — chercheur de filons, disaient les mineurs de Deepdelve, de ceux qui remontent de moins en moins souvent. Il avait ce bracelet au poignet en mourant. Son fantôme a continué la prospection sans remarquer le changement. La mort n\'a pas jugé utile de rendre le bracelet. Elle a peut-être estimé qu\'il ne lui appartenait plus.', name: 'Bracelet du Fantôme', description: 'Porté par le revenant qui hantait les grottes de son vivant.', rarity: ItemRarity.RARE, type: ItemType.RING, icon: 'item_wraith_band', value: 380, bonusStats: {}, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 8, max: 12 }, substats: [{ key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_DMG', min: 28, max: 44, isPercentage: true }, { key: 'HP_ON_KILL_FLAT', min: 9, max: 14 }] } },
  { id: 'wraith_ice_amulet', lore: 'Les fantômes blizzards de Glaciem sont des tempêtes qui ont oublié de finir. Celui-ci a été replié dans une amulette par un procédé que les chasseurs de Frostveil ne consignent pas — par prudence, ou par honte. Le blizzard y tient tout entier. Collée à l\'oreille, on l\'entend tourner, et parfois autre chose que le vent. Ne l\'écoutez pas trop longtemps.', name: 'Amulette du Fantôme Blizzard', description: 'Le froid de Glaciem sous forme condensée.', rarity: ItemRarity.RARE, type: ItemType.AMULET, icon: 'item_blizzard_amulet', value: 380, element: ElementType.ICE, bonusStats: {}, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 10, max: 16 }, substats: [{ key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'SPD_FLAT', min: 4, max: 7 }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }] } },
  { id: 'frozen_heart_amulet', lore: 'Le cœur d\'un dragon de cristal, pris dans la glace de Crysthea avant d\'avoir fini de s\'arrêter. Il bat une fois par heure, exactement — les horlogers de Frostveil ont vérifié pendant vingt ans sans le prendre en défaut. Un battement par heure, ce n\'est pas assez pour vivre. C\'est juste assez pour attendre. Personne ne sait pour qui.', name: 'Cœur Gelé', description: 'Le cœur d\'un dragon de cristal, préservé dans la glace. Bat encore.', rarity: ItemRarity.EPIC, type: ItemType.AMULET, icon: 'item_frozen_heart', value: 1200, element: ElementType.ICE, bonusStats: {}, passiveEffect: 'ICE_SLOW_15_PCT', equipRanges: { mainStat: { key: 'ATK_FLAT', min: 13, max: 20 }, substats: [{ key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'BOSS_DMG_PCT', min: 12, max: 18, isPercentage: true }, { key: 'ATK_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }] } },
  { id: 'thunder_drake_fang', lore: 'Les enfants de Volterra en portaient pour se donner du courage — une dent de drake au bout d\'un cordon, troquée contre des billes ou des services. Le picotement dans la paume passait pour un secret entre soi et l\'orage. Les pendentifs ont duré plus longtemps qu\'eux. On en trouve encore aux marchés, cordons refaits à neuf.', name: 'Pendentif-Croc du Drake', description: 'La dent brisée d\'un drake du tonnerre sur un cordon.', rarity: ItemRarity.UNCOMMON, type: ItemType.AMULET, icon: 'item_drake_fang', value: 120, element: ElementType.LIGHTNING, bonusStats: {}, equipRanges: { mainStat: { key: 'ATK_FLAT', min: 8, max: 12 }, substats: [{ key: 'ELEM_BONUS_PCT', min: 5, max: 7, isPercentage: true }, { key: 'CRIT_RATE', min: 6, max: 9, isPercentage: true }] } },
];

